const identificationV2BaseAnalyze=analyze;
analyze=function(img){const out=identificationV2BaseAnalyze(img),knowledge=typeof BOTANICAL_KNOWLEDGE==='undefined'?null:BOTANICAL_KNOWLEDGE;out.identification_v2=IdentificationV2.build(out,knowledge);return out;};
render=function(out){
 lastOutput=out;const pipeline=out.identification_v2,esc=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'),human=value=>String(value??'unresolved').replaceAll('_',' '),triage=pipeline.triage;
 const triageRows=[['Framing / scale',triage.framing],['Flower candidates',triage.flower_multiplicity],['Visible floral structure',triage.visible_floral_structure],['Leaf visibility',triage.leaf_visibility]];
 $('triageCards').innerHTML=triageRows.map(([title,item])=>`<section class="triage-card ${item?.status==='needs_extra_handling'?'attention':''}"><h3>${esc(title)}</h3><strong>${esc(human(item?.value))}</strong><p>${esc(item?.reason||'Unresolved')}</p></section>`).join('');
 const map=pipeline.evidence_map,comparisons=map.profile_comparisons||[],coverage=map.catalogue_coverage,knowledgeOnly=coverage.knowledge_only;
 $('evidenceMap').innerHTML=`<section class="map-step"><span>1 · PIXELS</span><strong>Image measurements</strong><ul>${map.image_processing.map(item=>`<li><b>${esc(item.label)}</b><em>${esc(human(item.value))}</em><small>${esc(item.source)}</small></li>`).join('')}</ul></section><i aria-hidden="true">→</i><section class="map-step"><span>2 · OBSERVATION</span><strong>${esc(human(map.observed_character.value))}</strong><p>${esc(map.observed_character.reason)}</p></section><i aria-hidden="true">→</i><section class="map-step ${comparisons.some(item=>item.status==='conflict')?'map-conflict':''}"><span>3 · PLANT KNOWLEDGE</span><strong>Top candidate comparisons</strong><ul>${comparisons.map(item=>`<li><b>${esc(item.candidate_name)}</b><em>${esc(human(item.status))}</em><small>${esc(human(item.observed))} → ${esc((item.expected||[]).map(human).join(' / ')||'not reviewed')} · inspect only</small></li>`).join('')}</ul>${knowledgeOnly.length?`<details><summary>${knowledgeOnly.length} knowledge-only match${knowledgeOnly.length===1?'':'es'}</summary><p>${knowledgeOnly.slice(0,6).map(item=>esc(item.name)).join(' · ')}</p></details>`:''}</section><i aria-hidden="true">→</i><section class="map-step ${map.gate.passed?'map-pass':'map-stop'}"><span>4 · DECISION GATE</span><strong>${map.gate.passed?'Primary complete':'Review required'}</strong><p>${map.gate.blockers.length?map.gate.blockers.map(human).join(' · '):'All declared predicates passed'}</p></section>`;
 const gate=pipeline.primary.gate,predicates=Object.entries(gate.predicates),families=Object.entries(pipeline.primary.evidence_families);
 const predicateGroups=[['IMAGE READINESS',['analyzable','framing_usable','single_target']],['IDENTIFICATION EVIDENCE',['coverage_sufficient','required_traits_present','independent_groups_sufficient','score_sufficient','lead_sufficient']],['VALIDATION POLICY',['profile_validated']]];
 $('featureRows').innerHTML=`<div class="gate-summary"><strong>${gate.passed?'PRIMARY COMPLETE':'REVIEW REQUIRED'}</strong><span>${pipeline.primary.candidates[0]?.pipeline_score.toFixed(3)||'—'} · lead ${pipeline.primary.lead.toFixed(3)}</span></div><div class="predicate-groups">${predicateGroups.map(([title,names])=>`<section><h3>${title}</h3><div class="predicate-list">${names.map(name=>{const pass=gate.predicates[name];return`<div class="predicate ${pass?'pass':'fail'}"><b>${pass?'✓':'×'}</b><span>${esc(human(name))}</span></div>`}).join('')}</div></section>`).join('')}</div><div class="family-strip">${families.map(([name,status])=>`<span>${esc(human(name))}: ${esc(human(status))}</span>`).join('')}</div>`;
 $('secondaryStatus').textContent=pipeline.secondary.ran?'RAN · BOUNDED RERANK':'SKIPPED';
 $('secondaryRoute').textContent=pipeline.secondary.reason;
 $('leafEvidence').textContent=pipeline.secondary.available?'Visible blade candidate':'No reliable blade';
 const changed=pipeline.secondary.changes.filter(change=>Math.abs(change.adjustment)>.00001||change.before_rank!==change.after_rank);
 $('rankChanges').textContent=changed.length?`${changed.length} candidate${changed.length===1?'':'s'} changed`:'None';
 const final=pipeline.final,top=final.candidates[0],identified=final.outcome==='identified',leader=final.leading_candidate,ties=final.leading_candidates||[];
 $('prediction').textContent=identified?final.candidate_name:final.outcome==='no_match'?'NO SUPPORTED MATCH':ties.length>1?`AMBIGUOUS · ${ties.length}-WAY TIE`:leader?leader.name+' · CANDIDATE':'AMBIGUOUS';
 $('latin').textContent=ties.length>1?ties.map(item=>item.name).join(' · '):leader?(leader.latin||'—')+(identified?'':' · not confirmed'):'Review required · no automatic acceptance';
 $('decision').textContent=human(final.outcome).toUpperCase();$('plantPart').textContent=human(final.internal_state);$('growthStage').textContent=identified?human(top?.stage):'Unresolved';$('topScore').textContent=top?.pipeline_score.toFixed(3)||'—';$('leadScore').textContent=final.lead.toFixed(3);$('decisionLog').textContent=final.reason;$('followUp').textContent='Next evidence: '+final.follow_up;
 $('ambiguityReasons').innerHTML=(pipeline.ambiguity?.causes||[]).map(cause=>`<li><b>${esc(human(cause.code))}</b><span>${esc(cause.message)}</span></li>`).join('');
 $('runStatus').textContent=final.outcome==='identified'?'EXPERIMENTAL ID':final.outcome==='no_match'?'NO MATCH':'REVIEW REQUIRED';$('runStatus').className='status '+(final.outcome==='identified'?'pass':final.internal_state==='not_assessable'?'reject':'idle');
 const changes=new Map(pipeline.secondary.changes.map(change=>[change.id,change]));
 $('candidateRows').innerHTML=final.candidates.map(row=>{const change=changes.get(row.id),delta=change?.adjustment||0,s=row.structure_evidence;return `<tr><td>${row.pipeline_rank}</td><td>${esc(row.name)}<br><small>${esc(row.stage)} · ${esc(row.taxonRank)}</small></td><td><span class="structure-state ${esc(s.status)}">${esc(human(s.status))}</span><br><small>${esc(human(s.observed))} → ${esc((s.expected||[]).map(human).join(' / ')||'not reviewed')} · inspect only</small></td><td>${change?.before_score.toFixed(3)||row.pipeline_score.toFixed(3)}</td><td>${row.pipeline_score.toFixed(3)}</td><td class="${delta<0?'delta-negative':delta>0?'delta-positive':''}">${delta>=0?'+':''}${delta.toFixed(3)}</td><td>${Math.round((row.coverage||0)*100)}%</td></tr>`}).join('');
 $('rawOutput').textContent=JSON.stringify(pipeline,null,2);$('copyButton').disabled=false;
};
